// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        // Record the pre-initialization MinSum chosen by the fuzzer.
        vm.prank(address(1));
        c.SetMinSum(v1);
        uint256 before = c.MinSum();

        // Initialize the contract: from now on SetMinSum must be frozen.
        vm.prank(address(2));
        c.Initialized();

        // After initialization, SetMinSum must revert for EVERY input.
        bool ok;
        vm.prank(address(3));
        try c.SetMinSum(v2) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.MinSum() == before);
    }
}
